config.jsonSchemaText:
{
    "type": "object",
    "properties": {
      "zusammenfassung": {
        "type": "string",
        "description": "Sachliche Zusammenfassung des Anliegens, max. 3 Sätze."
      },
      "kritikalitaet": {
        "type": "string",
        "enum": ["Kritisch", "Hoch", "Mittel", "Niedrig", "Other"]
      },
	  "firmenname": {
        "type": "string",
        "description": "Der Name der Firma."
      },
	  "ansprechpartner": {
        "type": "string",
        "description": "Der Name des Ansprechpartners."
      },
	  "telefonnummer": {
        "type": "string",
        "description": "Die Telefonnummer des Ansprechpartners oder der Firma."
      }
    },
    "required": ["zusammenfassung", "kritikalitaet", "firmenname", "ansprechpartner", "telefonnummer"]
  }
